<?php
namespace Tests\Unit;
use App\Models\{Employe,RhHoraire};use App\Services\RhPresenceCalculationService;use PHPUnit\Framework\TestCase;
class HumanResourcesAttendanceCalculationTest extends TestCase {public function test_work_pause_delay_early_departure_and_overtime_are_calculated():void{$h=new RhHoraire(['heure_debut'=>'08:00:00','heure_fin'=>'17:00:00','pause_minutes'=>60,'heures_normales'=>8,'tolerance_retard_minutes'=>5]);$e=new Employe;$e->setRelation('horaire',$h);$r=(new RhPresenceCalculationService)->calculate($e,['date'=>'2026-09-01','heure_arrivee'=>'08:15','debut_pause'=>'12:00','fin_pause'=>'12:30','heure_depart'=>'17:45']);$this->assertSame(9.0,$r['heures_travaillees']);$this->assertSame(10,$r['retard_minutes']);$this->assertSame(0,$r['depart_anticipe_minutes']);$this->assertSame(1.0,$r['heures_supplementaires']);}public function test_an_iso_model_date_is_normalized_before_times_are_added():void{$h=new RhHoraire(['heure_debut'=>'08:00:00','heure_fin'=>'17:00:00','pause_minutes'=>60,'heures_normales'=>8,'tolerance_retard_minutes'=>0]);$e=new Employe;$e->setRelation('horaire',$h);$r=(new RhPresenceCalculationService)->calculate($e,['date'=>'2026-08-27T23:00:00.000000Z','heure_arrivee'=>'08:00:00','heure_depart'=>'17:00:00']);$this->assertSame(8.0,$r['heures_travaillees']);$this->assertSame(0,$r['retard_minutes']);}}
